import { localizedPrice, type PriceSearchParams } from "@/lib/localized-price";
import { requireUser } from "@/lib/session";
import { readBillingStatus } from "@/lib/billing/status";
import { UsageContent } from "@/components/usage/UsageContent";
export const metadata = { title: "Usage" };
export default async function UsagePage({
  searchParams,
}: {
  searchParams: PriceSearchParams;
}) {
  const user = await requireUser();
  const [billing, price] = await Promise.all([
    readBillingStatus(user.id),
    localizedPrice(searchParams),
  ]);
  return <UsageContent initialBilling={billing} advertisedPrice={price} />;
}
